<template><div class="member-list"><div v-if="!members?.length" class="empty">暂无会员</div><article v-for="m in members" :key="m.member_id||m.id" class="member-row" @click="$emit('open',m)"><div class="avatar">{{ (m.name||'?').slice(0,1) }}</div><div class="member-main"><b>{{ m.name }}</b><p>{{ maskPhone(m.phone) }} <span class="tag">{{ formatTags(m.tags) }}</span></p><small>累计消费 ¥{{ Number(m.total_consume||0).toFixed(2) }}</small></div><button v-if="!sales && !m.sales_id" class="outline" @click.stop="claimMember(m)">认领</button><span class="chevron">›</span></article></div></template><script setup>import { api } from '../api/request.js';import { maskPhone, formatTags } from '../utils/format.js';const props=defineProps({members:Array,sales:Boolean});const emit=defineEmits(['open','claim']);async function claimMember(m){try{await api.claimMember(m.member_id||m.id);m.sales_id=true;emit('claim',m)}catch(e){alert(e.message)}}</script>
